-- Ingredient library expansion, part 3: 32 everyday ingredients.
--
--   preservation        hydroxyacetophenone (booster), chlorphenesin
--   emulsifiers         sorbitan stearate and oleate (Span 60 / 80), ceteareth-20, glycol distearate (pearlizer)
--   emollients, waxes   diisopropyl adipate, ethylhexyl palmitate, cetyl esters, castor wax, microcrystalline wax,
--                       phenyl trimethicone, cetyl dimethicone
--   cleansing           cocamide MEA
--   oils and butters    borage, chia, camelina, sacha inchi, tea seed, sal butter
--   actives             dimethylmethoxy chromanol (Lipochroman-6), ergothioneine, octinoxate (UV filter)
--   adjusters, powders  potassium hydroxide, malic acid, calcium carbonate, magnesium stearate, microcrystalline cellulose,
--                       hydroxypropyl starch phosphate
--   extracts            burdock root, echinacea, seaweed (Ascophyllum nodosum)
--
-- Every INCI name was checked against the EU glossary of common ingredient names (Commission Implementing Decision (EU)
-- 2025/1175), so each can be written on a label as it appears here. None of them was in the library yet.
--
-- The figures come from public supplier datasheets and reference pages, and are typical ranges, not legal limits (the legal
-- limits are checked separately in the selling-limits panel). Where the sources disagree or no reliable figure was found,
-- the row says so in its notes: comedogenic ratings of plant oils are estimates, a few CAS numbers are "N/A" because suppliers
-- list different ones, and extract strengths differ between suppliers. Extract COSMOS status is marked "not compliant" so the claim
-- check asks you to look at the supplier's certificate instead of approving it.
--
-- A row is only added when no ingredient with the same INCI name and trade name exists, so this is safe to run more than once.


insert into public.ingredients (id, inci_name, trade_name, function, min_usage_pct, max_usage_pct, cas_number, solubility, ionic_charge, physical_state, optimal_ph_min, optimal_ph_max, max_heating_temp_c, is_vegan, is_cosmos, cost_category, description, common_uses, is_sulfate, is_silicone, is_paraben, is_fragrance, cosmos_compliant, comedogenic_rating, default_min_usage, default_max_usage, notes)
select gen_random_uuid(), 'Hydroxyacetophenone', 'Hydroxyacetophenone (4-HAP)', 'Preservative Booster', 0.1, 1, '99-93-4', 'water', 'non-ionic', 'powder', 3, 10, 80, true, false, 'medium', 'A mild booster that makes a main preservative work better and also has an antioxidant effect. It is not a complete preservative on its own.', 'Creams, lotions, serums, cleansers; often paired with phenoxyethanol or a glycol', false, false, false, false, false, 0, 0.3, 1, 'Does not preserve a formula by itself: use it with a main preservative (often 50:50 with phenoxyethanol) and a glycol. Dissolves to about 1% in water and better in glycols or glycerin, so dissolve it in a warm glycol first. Up to 1% is the usual ceiling.'
 where not exists (select 1 from public.ingredients i where lower(i.inci_name) = lower('Hydroxyacetophenone') and lower(i.trade_name) = lower('Hydroxyacetophenone (4-HAP)'));

insert into public.ingredients (id, inci_name, trade_name, function, min_usage_pct, max_usage_pct, cas_number, solubility, ionic_charge, physical_state, optimal_ph_min, optimal_ph_max, max_heating_temp_c, is_vegan, is_cosmos, cost_category, description, common_uses, is_sulfate, is_silicone, is_paraben, is_fragrance, cosmos_compliant, comedogenic_rating, default_min_usage, default_max_usage, notes)
select gen_random_uuid(), 'Chlorphenesin', 'Chlorphenesin', 'Preservative (Antifungal)', 0.1, 0.3, '104-29-0', 'dispersible', 'non-ionic', 'powder', 4, 8, 80, true, false, 'medium', 'A preservative that works mainly against yeast, mold and gram-positive bacteria. It is allowed up to 0.3% in the EU.', 'Creams, lotions, cleansers, as part of a preservative system', false, false, false, false, false, 0, 0.2, 0.3, 'Allowed up to 0.3% in the EU (Annex V). Weaker against gram-negative bacteria, so combine it with phenoxyethanol or another broad-spectrum preservative. Dissolve it in warm glycol or in the hot water phase.'
 where not exists (select 1 from public.ingredients i where lower(i.inci_name) = lower('Chlorphenesin') and lower(i.trade_name) = lower('Chlorphenesin'));

insert into public.ingredients (id, inci_name, trade_name, function, min_usage_pct, max_usage_pct, cas_number, solubility, ionic_charge, physical_state, optimal_ph_min, optimal_ph_max, max_heating_temp_c, is_vegan, is_cosmos, cost_category, description, common_uses, is_sulfate, is_silicone, is_paraben, is_fragrance, cosmos_compliant, comedogenic_rating, default_min_usage, default_max_usage, notes)
select gen_random_uuid(), 'Sorbitan Stearate', 'Sorbitan Stearate (Span 60)', 'Emulsifier', 0.5, 5, '1338-41-6', 'oil', 'non-ionic', 'solid', 4, 9, 85, true, false, 'low', 'A low-HLB (about 4.7) emulsifier. On its own it favors water-in-oil; paired with a high-HLB emulsifier such as a polysorbate it makes stable creams.', 'Creams, lotions, balms and sunscreens, as a co-emulsifier', false, false, false, false, false, 1, 1, 3, 'Melts with the oil phase. Usually vegetable in origin, but ask your supplier for a certificate if you need to claim vegan.'
 where not exists (select 1 from public.ingredients i where lower(i.inci_name) = lower('Sorbitan Stearate') and lower(i.trade_name) = lower('Sorbitan Stearate (Span 60)'));

insert into public.ingredients (id, inci_name, trade_name, function, min_usage_pct, max_usage_pct, cas_number, solubility, ionic_charge, physical_state, optimal_ph_min, optimal_ph_max, max_heating_temp_c, is_vegan, is_cosmos, cost_category, description, common_uses, is_sulfate, is_silicone, is_paraben, is_fragrance, cosmos_compliant, comedogenic_rating, default_min_usage, default_max_usage, notes)
