select gen_random_uuid(), 'Glycol Distearate', 'Glycol Distearate (Pearlizer)', 'Texture Enhancer', 0.5, 5, '627-83-8', 'oil', 'non-ionic', 'solid', 4, 9, 85, true, false, 'low', 'A waxy pearlizer that gives shampoos, body washes and hand soaps a pearly, opaque look.', 'Shampoos, body washes, liquid hand soaps, creams', false, false, false, false, false, 1, 1, 3, 'Melt it into the surfactant base at about 70-75°C and cool slowly while stirring: fast cooling gives a dull, not pearly, result. Usually vegetable in origin, but ask your supplier for a certificate if you need to claim vegan.'
